"""Writes the CP949 table (no arguments) or re-encodes a UTF-8 fixture as CP949 (--fixture IN OUT)."""
import argparse
import base64
import pathlib
import struct

ROOT = pathlib.Path(__file__).resolve().parent.parent
TABLE_TS = ROOT / "packages" / "library" / "src" / "subtitles" / "cp949-table.ts"
HEAD = (
    "// Generated by scripts/build-cp949.py — do not edit. "
    "Python's cp949 codec equals the WHATWG index-euc-kr (17,048 pointers).\n"
)


def build_table() -> None:
    values = []
    for lead in range(0x81, 0xFF):
        for trail in range(0x41, 0xFF):
            try:
                s = bytes([lead, trail]).decode("cp949")
            except UnicodeDecodeError:
                values.append(0)
                continue
            values.append(ord(s) if len(s) == 1 else 0)
    assert len(values) == 126 * 190
    assert sum(1 for v in values if v) == 17048
    assert all(v <= 0xFFFF for v in values)
    b64 = base64.b64encode(struct.pack("<%dH" % len(values), *values)).decode("ascii")
    lines = [b64[i : i + 76] for i in range(0, len(b64), 76)]
    body = "export const CP949_TABLE_B64 = [\n" + "".join("  '%s',\n" % l for l in lines) + "].join('');\n"
    TABLE_TS.write_text(HEAD + body, encoding="utf-8")


def build_fixture(src: str, dst: str) -> None:
    text = pathlib.Path(src).read_bytes().decode("utf-8")
    pathlib.Path(dst).write_bytes(text.encode("cp949"))


def main() -> None:
    p = argparse.ArgumentParser()
    p.add_argument("--fixture", nargs=2, metavar=("IN", "OUT"))
    a = p.parse_args()
    if a.fixture:
        build_fixture(*a.fixture)
    else:
        build_table()


main()
